 "content": "def transform(grid):
    # Expands the single row into a triangular fan: 2s travel outward diagonally,
    # then 1s continue the periodic diagonal pattern.
    n = len(grid[0])
    center = next(i for i, v in enumerate(grid[0]) if v == 2)
    out = [[0] * n for _ in range(n)]
    # 2 border rays move out one column per row until the edges.
    for r in range(n):
        left, right = center-r, center+r
        if 0 <= left < n: out[r][left] = 2
        if 0 <= right < n: out[r][right] = 2
    # interior 1 pattern starts in row 3, stepping by 3 columns each row;
    # equivalently all points whose (column + row) modulo 3 matches center.
    for r in range(n):
        for c in range(n):
            if out[r][c] == 0 and r >= 3 and (c + r - center) % 3 == 0:
                out[r][c] = 1
    return out
